# Rebuild with int sample keys
import json, re
rows = [json.loads(l) for l in open('/practice/baseline/original.jsonl')]
by_key = {(r['qid'], r['sample']): r for r in rows}
probe = [('math/geometry/621',0), ('math/geometry/621',1), ('math/intermediate_algebra/1024',0), ('math/algebra/231',0)]
corr = [('math/algebra/530',0), ('math/algebra/530',1)]
def trunc_after_cascade(t, n_think=5, tail_chars=200):
    idxs = [m.start() for m in re.finditer(re.escape('</think>'), t)]
    if len(idxs) >= n_think:
        return t[:idxs[n_think-1] + tail_chars]
    return t[:6000]
texts = {}
for qid, s in probe:
    texts[f'fail|{qid}|{s}'] = trunc_after_cascade(by_key[(qid,s)]['text'])
for qid, s in corr:
    texts[f'ok|{qid}|{s}'] = by_key[(qid,s)]['text'][:6500]
tot=0
for k,v in texts.items():
    n=len(tok.encode(v).ids); tot+=n
    print(k, 'chars', len(v), 'tokens', n, 'n_</think>', v.count('</think>'))
print('total tokens', tot)

# Fetch problem texts for the chat messages
import json
probs = {}
with open('/practice/problems.jsonl') as f:
    for line in f:
        d = json.loads(line)
        if d['id'] in ('math/geometry/621','math/intermediate_algebra/1024','math/algebra/231'):
            probs[d['id']] = d['problem']
for k,v in probs.items():
    print('='*80); print(k); print(v[:400])

# Does tok.encode map literal </think> to the special token?
for s in ['</think>', 'but wait.\n</think>\n\nThe answer', 'a</think>b']:
    print(repr(s), tok.encode(s).ids)

